		if (abs(P.y - waist) < 0.03 || (arm > 0.5 && vCuff < 0.05) || (s == 2 && P.y < ankle + 0.1) || (P.z > 0.0 && abs(P.x) < 0.012 && P.y > waist - 0.2)) c = a;
